    # ==========================================
    # DAY 26: Hybrid & Multi-Cloud AI Architecture
    # ==========================================
    d26_easy = [
        ("Hybrid Cloud Foundations", "Mô hình 'Hybrid Cloud' (Đám mây Lai) trong hạ tầng AI là sự kết hợp giữa những môi trường nào?",
         ["Kết hợp giữa máy tính bảng và điện thoại", "Kết hợp giữa Trung tâm Dữ liệu Cục bộ Nội bộ (On-Premise Private Data Center) và Đám mây Công cộng (Public Cloud như AWS, GCP, Azure)", "Kết hợp giữa đĩa mềm và ổ cứng", "Kết hợp giữa cáp quang và sóng radio"], 1,
         "Đám mây lai cho phép doanh nghiệp tận dụng tối đa hạ tầng máy chủ GPU cố định nội bộ trong khi vẫn có thể mở rộng đột biến lên đám mây công cộng khi có nhu cầu.", "Day 26 - Slide: Hybrid Cloud AI Foundations"),
        ("Multi-Cloud Strategy", "Tại sao các tập đoàn lớn lại áp dụng 'Chiến lược Đa Đám mây' (Multi-Cloud Strategy sử dụng đồng thời cả AWS, GCP và Azure)?",
         ["Để làm cho hệ thống phức tạp hơn", "Tránh bị Phụ thuộc Độc quyền vào Một Nhà Cung cấp (Vendor Lock-In), Tận dụng thế mạnh phần cứng chuyên biệt của từng hãng (ví dụ: TPU trên GCP, Trainium trên AWS), Tối ưu hóa chi phí và Tăng cường khả năng Phục hồi Thảm họa", "Vì các công ty đám mây bắt buộc phải dùng chung", "Vì một đám mây không đủ chỗ chứa dữ liệu"], 1,
         "Chiến lược Đa đám mây bảo vệ doanh nghiệp khỏi rủi ro gián đoạn dịch vụ của một nhà cung cấp và tối đa hóa khả năng đàm phán thương mại.", "Day 26 - Slide: Multi-Cloud Strategy & Benefits"),
        ("Direct Connect / Cloud Interconnect", "Dịch vụ AWS Direct Connect hoặc GCP Dedicated Interconnect cung cấp đường truyền mạng như thế nào?",
         ["Đường truyền Wi-Fi công cộng miễn phí", "Kênh truyền dẫn Cáp quang Chuyên dụng Riêng biệt (Dedicated Physical Fiber Connection) kết nối trực tiếp từ Trung tâm Dữ liệu On-Premise tới Đám mây với Băng thông khổng lồ (100Gbps+) và Độ trễ cực thấp ổn định", "Đường truyền qua sóng vệ tinh", "Đường dây điện thoại bàn"], 1,
         "Direct Connect cung cấp đường cao tốc mạng riêng tư, ổn định và bảo mật cao, là xương sống của mọi kiến trúc đám mây lai.", "Day 26 - Slide: Dedicated Cloud Interconnects"),
        ("Model Portability: ONNX", "Định dạng ONNX (Open Neural Network Exchange) mang lại khả năng gì cho mô hình AI?",
         ["Biến mô hình thành file âm thanh", "Khả năng Khả chuyển (Model Portability): Cho phép một mô hình được huấn luyện bằng bất kỳ framework nào (PyTorch, TensorFlow) có thể xuất khẩu sang một định dạng chung duy nhất để chạy trên mọi nền tảng phần cứng và đám mây", "Khóa mô hình không cho ai sử dụng", "Tự động dịch mã nguồn sang tiếng Pháp"], 1,
         "ONNX chuẩn hóa cấu trúc đồ thị tính toán của mạng nơ-ron, giải phóng mô hình khỏi sự ràng buộc của từng framework hoặc phần cứng cụ thể.", "Day 26 - Slide: ONNX & Model Portability Standards"),
        ("Multi-Cloud Disaster Recovery", "Trong kịch bản Phục hồi Thảm họa Đa Đám mây (Multi-Cloud Disaster Recovery), mục tiêu của 'RTO' (Recovery Time Objective) là gì?",
         ["Số tiền bồi thường bảo hiểm", "Thời gian tối đa cho phép để toàn bộ hệ thống AI khôi phục lại hoạt động bình thường trên đám mây dự phòng sau khi đám mây chính bị sập hoàn toàn (ví dụ: RTO < 5 phút)", "Thời gian nhân viên đi làm lại", "Số lượng ổ cứng bị hỏng"], 1,
         "RTO đo lường tốc độ khôi phục dịch vụ, là chỉ số cam kết sống còn trong các kế hoạch ứng phó thảm họa hạ tầng.", "Day 26 - Slide: Disaster Recovery Objectives: RTO and RPO"),
        ("Data Sovereignty & Compliance", "Yêu cầu 'Chủ quyền Dữ liệu' (Data Sovereignty) quy định điều gì đối với việc lưu trữ dữ liệu người dùng?",
         ["Dữ liệu thuộc quyền sở hữu của công ty đám mây", "Dữ liệu cá nhân và nhạy cảm của công dân BẮT BUỘC PHẢI ĐƯỢC LƯU TRỮ VÀ XỬ LÝ TRONG PHẠM VI RANH GIỚI ĐỊA LÝ của quốc gia đó (ví dụ: Lưu trữ tại On-Premise hoặc Data Center nội địa theo quy định pháp luật)", "Dữ liệu phải được công khai trên internet", "Dữ liệu chỉ được lưu trữ trên tàu vũ trụ"], 1,
         "Chủ quyền dữ liệu là lý do chính khiến các tổ chức tài chính và chính phủ lựa chọn kiến trúc đám mây lai để giữ dữ liệu nhạy cảm tại chỗ.", "Day 26 - Slide: Data Sovereignty and Compliance in Hybrid AI"),
        ("Cross-Cloud Data Synchronization", "Công cụ nào sau đây thường được sử dụng để đồng bộ hóa các tệp dữ liệu lớn giữa AWS S3 và Google Cloud Storage?",
         ["GCP Storage Transfer Service hoặc Rclone", "Microsoft Word", "Photoshop", "VLC Media Player"], 0,
         "Storage Transfer Service và Rclone là các công cụ chuyên dụng tự động hóa việc di chuyển dữ liệu phân tán quy mô lớn giữa các đám mây.", "Day 26 - Slide: Cross-Cloud Data Synchronization Tools"),
        ("Edge-to-Cloud Continuum", "Khái niệm 'Edge-to-Cloud Continuum' trong AI mô tả điều gì?",
         ["Một đường thẳng vô tận trong không gian", "Dòng chảy tính toán liền mạch trải dài từ Thiết bị Biên (Sensors/Điện thoại) -> Máy chủ Biên Cục bộ (Edge Servers) -> Trung tâm Dữ liệu On-Premise -> Đám mây Công cộng (Cloud)", "Một loại cáp mạng mới", "Một phần mềm diệt virus"], 1,
         "Edge-to-Cloud Continuum phân bổ thông minh các tác vụ xử lý dữ liệu và suy luận AI tới vị trí tối ưu nhất dọc theo chuỗi hạ tầng.", "Day 26 - Slide: Edge-to-Cloud Continuum Architecture"),
        ("Cloud Bursting", "Khái niệm 'Cloud Bursting' trong kiến trúc Hybrid AI hoạt động như thế nào?",
         ["Máy chủ bị nổ tung khi quá tải", "Hệ thống chạy các tác vụ thường ngày trên Cụm GPU On-Premise cố định; Khi có đợt bùng nổ tải vượt quá công suất cục bộ, hệ thống tự động 'Tràn' (Burst) và khởi chạy thêm các Worker Pods trên Đám mây Công cộng để xử lý", "Tắt toàn bộ hệ thống khi có tải lớn", "Bắt người dùng phải chờ đợi"], 1,
         "Cloud Bursting tối ưu hóa chi phí bằng cách tận dụng phần cứng nội bộ cho tải nền và chỉ thuê đám mây ngắn hạn khi có đỉnh tải đột biến.", "Day 26 - Slide: Cloud Bursting for AI Workloads"),
        ("Unified Control Plane (Anthos / EKS Anywhere / Azure Arc)", "Các nền tảng như Google Anthos, AWS EKS Anywhere hoặc Azure Arc đóng vai trò gì?",
         ["Soạn thảo văn bản", "Cung cấp một Tầng Điều khiển Hợp nhất (Unified Control Plane): Cho phép quản lý, triển khai và giám sát các Cụm Kubernetes phân tán trên cả On-Premise, AWS, GCP và Azure từ một giao diện quản trị duy nhất", "Thay thế toàn bộ các card đồ họa", "Chơi game trực tuyến"], 1,
         "Unified Control Plane trừu tượng hóa sự khác biệt giữa các nhà cung cấp, mang lại trải nghiệm vận hành Cloud-Native nhất quán trên mọi môi trường.", "Day 26 - Slide: Unified Hybrid Control Planes"),
        ("Model Registry Across Multi-Cloud", "Làm thế nào để các kỹ sư đảm bảo rằng một mô hình AI đã được kiểm duyệt tại AWS có thể được triển khai ngay lập tức lên GCP?",
         ["Tải mô hình lên mạng xã hội và gửi link", "Sử dụng một Kho Đăng bạ Mô hình Đa Đám mây Tập trung (Multi-Cloud Centralized Model Registry on MLflow / Harbor): Tự động nhân bản Artifacts và Container Images sang các Registry khu vực tương ứng của từng đám mây", "Bắt kỹ sư phải huấn luyện lại mô hình từ đầu trên GCP", "Không thể triển khai mô hình xuyên đám mây"], 1,
         "Centralized Model Registry chuẩn hóa việc phân phối tạo tác mô hình, đảm bảo tính nhất quán của phiên bản phát hành trên toàn cầu.", "Day 26 - Slide: Centralized Multi-Cloud Model Registries"),
        ("Global Traffic Management (GTM)", "Hệ thống Global Traffic Management (như Cloudflare / AWS Route 53) phân phối lưu lượng người dùng tới các đám mây như thế nào?",
         ["Gửi tất cả người dùng tới một máy chủ duy nhất", "Sử dụng định tuyến Anycast DNS và Geolocation Routing: Tự động chuyển hướng yêu cầu của người dùng tới Trung tâm Dữ liệu hoặc Đám mây gần nhất có độ trễ mạng thấp nhất và đang hoạt động khỏe mạnh", "Phân phối ngẫu nhiên không theo quy luật", "Chỉ gửi lưu lượng vào ban ngày"], 1,
         "Global Traffic Management tối ưu hóa độ trễ mạng toàn cầu và tự động chuyển hướng lưu lượng (Failover) khi một đám mây gặp sự cố.", "Day 26 - Slide: Global Traffic Management & Latency Routing"),
        ("Data Gravity Concept", "Hiện tượng 'Trọng lực Dữ liệu' (Data Gravity) trong kiến trúc đám mây ám chỉ điều gì?",
         ["Dữ liệu bị rơi xuống đất do lực hút trái đất", "Tập dữ liệu càng lớn (hàng Petabytes) thì càng khó khăn, tốn kém và mất thời gian để di chuyển sang nơi khác; Do đó, các ứng dụng tính toán và mô hình AI có xu hướng bị 'Hút' về nơi dữ liệu đang cư trú", "Dữ liệu làm tăng trọng lượng của ổ cứng", "Dữ liệu tự động biến mất khi nặng quá"], 1,
         "Data Gravity đòi hỏi các kiến trúc sư phải đặt năng lực tính toán AI gần kho dữ liệu lớn để tránh chi phí truyền tải và độ trễ khổng lồ.", "Day 26 - Slide: Data Gravity & Compute Locality"),
        ("Egress Cost Awareness", "Chi phí 'Data Egress Cost' (Chi phí Xuất Dữ liệu ra ngoài) trên các đám mây công cộng là gì?",
         ["Phí vào cổng trung tâm dữ liệu", "Khoản phí mà các nhà cung cấp đám mây (AWS/GCP/Azure) thu khi bạn chuyển dữ liệu TỪ BÊN TRONG đám mây của họ RA NGOÀI INTERNET hoặc sang một nhà cung cấp đám mây khác (thường từ $0.05 - $0.09 / GB)", "Phí sử dụng bàn phím", "Phí cài đặt hệ điều hành"], 1,
         "Data Egress Cost là rào cản tài chính lớn trong kiến trúc đa đám mây, đòi hỏi các giải pháp nén và tối ưu hóa luồng truyền dữ liệu xuyên đám mây.", "Day 26 - Slide: Cloud Egress Costs & Financial Governance"),
        ("Multi-Cloud Networking: Transit Gateway & VPN", "Dịch vụ AWS Transit Gateway hoặc Multi-Cloud VPN kết nối các mạng ảo (VPCs) xuyên đám mây bằng cách nào?",
         ["Cắm trực tiếp dây cáp mạng giữa 2 màn hình", "Thiết lập các Đường hầm Mã hóa An toàn (Encrypted IPsec VPN Tunnels / BGP Peering) kết nối các mạng ảo riêng biệt (AWS VPC, GCP VPC, On-Premise) thành một Mạng Riêng Ảo Hợp nhất (Unified Mesh Network)", "Sử dụng sóng radio không mã hóa", "Gửi gói tin qua đường bưu điện"], 1,
         "Transit Gateway và Multi-Cloud VPN xây dựng đường ống giao tiếp an toàn, bảo vệ toàn bộ lưu lượng dữ liệu AI trao đổi giữa các môi trường đám mây.", "Day 26 - Slide: Multi-Cloud Secure Network Interconnects")
    ]

    d26_med = [
        ("Hybrid Cloud Bursting Architecture with KubeRay", "Quy trình Tự động Tràn tải (Automated Cloud Bursting Workflow) cho một Job huấn luyện Ray từ cụm On-Premise lên AWS EKS diễn ra theo các bước nào?",
         ["Tắt cụm On-premise và chuyển hết lên mây", "1. Ray Head Node (On-Premise) phát hiện hàng đợi Task bị nghẽn và toàn bộ GPU nội bộ đã đạt 100%; 2. Ray Autoscaler gọi KubeRay API trên AWS EKS khởi chạy một Cụm Worker Pods tạm thời (Spot GPU Instances); 3. Worker Nodes trên mây kết nối an toàn về Head Node qua Direct Connect; 4. Khi Job hoàn thành, Ray tự động tiêu hủy các Pods trên AWS", "Bắt người dùng phải tự thuê máy chủ AWS bằng tay", "Chỉ chạy các Job nhỏ lên mây"], 1,
         "KubeRay Autoscaler tự động hóa việc mở rộng cụm tính toán xuyên biên giới đám mây theo nhu cầu thực tế, tối đa hóa hiệu suất sử dụng tài nguyên.", "Day 26 - Slide: Automated Cloud Bursting with KubeRay"),
        ("Cross-Cloud Distributed Consensus with Raft over WAN", "Khi triển khai một Cụm Lưu trữ Trạng thái Mô hình (Consensus State Store như etcd / Consul) trải rộng trên 3 đám mây khác nhau, thách thức lớn nhất của thuật toán Raft là gì và cách giải quyết?",
         ["Thuật toán Raft không thể chạy trên đám mây", "Độ trễ mạng WAN cao và biến động (Network Jitter) làm tăng thời gian bầu chọn Leader (Heartbeat Timeout) và gây phân mảnh phiếu bầu; Giải pháp: Tăng tham số `heartbeat-interval` và `election-timeout` lên gấp 3 lần, kết hợp đặt Leader Node tại đám mây trung tâm có độ trễ trung bình thấp nhất", "Tắt toàn bộ cơ chế đồng thuận", "Chỉ sử dụng 1 máy tính duy nhất"], 1,
         "Hiệu chỉnh tham số thời gian chờ phù hợp với độ trễ mạng diện rộng đảm bảo cụm đồng thuận phân tán duy trì tính ổn định tuyệt đối xuyên đám mây.", "Day 26 - Slide: Cross-Cloud Raft Consensus & Latency Tuning"),
        ("Model Portability: TensorRT-LLM vs ONNX Runtime vs Triton", "Khi xây dựng một Tầng Phục vụ Mô hình Độc lập Đám mây (Cloud-Agnostic Serving Layer), kiến trúc kết hợp nào mang lại sự linh hoạt và hiệu năng cao nhất?",
         ["Viết lại code backend cho từng đám mây riêng biệt", "Sử dụng NVIDIA Triton Inference Server làm Máy chủ Phục vụ Tiêu chuẩn (Standard Container): Bên trong Triton nạp mô hình đã được tối ưu hóa bằng TensorRT-LLM (cho GPU NVIDIA) hoặc ONNX Runtime (cho CPU/AMD), cho phép triển khai cùng một container image trên bất kỳ nhà cung cấp nào", "Chỉ dùng Flask server đơn giản", "Cấm không cho sử dụng Triton"], 1,
         "Triton Inference Server đóng vai trò lớp trừu tượng hóa chuẩn mực, cho phép hoán đổi linh hoạt giữa các đám mây và phần cứng mà không cần sửa đổi mã nguồn ứng dụng.", "Day 26 - Slide: Cloud-Agnostic Serving Layer with Triton & ONNX"),
        ("Active-Active Multi-Cloud Disaster Recovery Architecture", "Sự khác biệt cốt lõi giữa Kiến trúc Phục hồi Thảm họa 'Active-Passive' và 'Active-Active' Đa Đám mây là gì?",
         ["Active-Active tốn ít chi phí hơn 100 lần", "Active-Passive: Đám mây phụ ở trạng thái chờ (Standby) và chỉ được bật khi đám mây chính sập (RTO tính bằng phút); Active-Active: Cả 2 đám mây ĐỀU ĐỒNG THỜI PHỤC VỤ LƯU LƯỢNG KHÁCH HÀNG 24/7, tự động cân bằng tải và tự động Failover tức thời trong < 1 giây (Zero RTO)", "Active-Passive không hỗ trợ sao lưu dữ liệu", "Cả 2 đều giống hệt nhau"], 1,
         "Active-Active cung cấp tính sẵn sàng tối đa 100% thời gian thực, loại bỏ hoàn toàn thời gian gián đoạn dịch vụ khi một nhà cung cấp đám mây gặp sự cố.", "Day 26 - Slide: Active-Active vs Active-Passive Multi-Cloud Architectures"),
        ("Minimizing Cross-Cloud Egress Costs with Delta Lake & CDC", "Làm thế nào để đồng bộ một Data Lakehouse 100TB từ AWS sang GCP hàng ngày mà không phải trả hàng chục nghìn USD tiền phí xuất dữ liệu (Data Egress Fees)?",
         ["Tải lại toàn bộ 100TB mỗi ngày", "Sử dụng Cơ chế Đồng bộ Dữ liệu Thay đổi (Change Data Capture - CDC & Delta Lake Time-Travel): Chỉ xuất và truyền tải duy nhất các tệp tin Parquet mới được Thêm/Sửa/Xóa (Delta Files) kết hợp nén Zstandard (Zstd) tối đa, giảm 98% khối lượng dữ liệu di chuyển qua mạng", "In dữ liệu ra giấy rồi nhập lại", "Không đồng bộ dữ liệu nữa"], 1,
         "Đồng bộ hóa vi mô dựa trên Delta Log và nén dữ liệu chặt chẽ giúp cắt giảm 98% chi phí băng thông xuất dữ liệu xuyên đám mây.", "Day 26 - Slide: Minimizing Multi-Cloud Data Egress with CDC & Delta Lake"),
        ("Hybrid Data Storage: Local Fast NVMe Cache + Multi-Cloud S3 Object Store", "Kiến trúc 'Hybrid Storage Tiering with S3-Compatible Storage' (như MinIO on-premise + AWS S3) tổ chức dòng dữ liệu cho cụm huấn luyện như thế nào?",
         ["Lưu tất cả dữ liệu trên đĩa mềm", "Dữ liệu gốc khổng lồ được lưu trữ vĩnh viễn trên AWS S3; Cụm máy chủ On-Premise triển khai MinIO / Alluxio hoạt động như một Cụm Bộ nhớ Đệm Cục bộ Tốc độ Cao (Local Distributed Read-Through Cache): Tự động tải trước và lưu đệm dữ liệu trên mảng SSD NVMe cục bộ để phục vụ GPU với thông lượng hàng chục GB/s", "Xóa dữ liệu trên đám mây sau khi tải về", "Bắt GPU phải đọc từng file qua mạng internet công cộng"], 1,
         "Kiến trúc bộ đệm phân tán cục bộ mang lại tốc độ truy xuất NVMe tức thời cho GPU nội bộ trong khi vẫn tận dụng được dung lượng lưu trữ không giới hạn của đám mây.", "Day 26 - Slide: Hybrid Storage Tiering with MinIO & S3"),
        ("Multi-Cloud Kubernetes Federation (KubeFed / Karmada)", "Công cụ Karmada (Kubernetes Multi-Cluster Management) điều phối các ứng dụng AI phân tán trên nhiều cụm Kubernetes như thế nào?",
         ["Tự động xóa các cụm Kubernetes phụ", "Đóng vai trò là Bộ điều phối Đa Cụm Thống nhất (Multi-Cluster Orchestrator): Cho phép định nghĩa một bản Deployment duy nhất và tự động phân phối các bản sao Pods (Replicas) tới các cụm EKS, GKE và On-Premise dựa trên chính sách phân bổ tài nguyên và chi phí", "Bắt lập trình viên phải cấu hình từng cụm riêng lẻ", "Chỉ hỗ trợ tối đa 1 cụm duy nhất"], 1,
         "Karmada mở rộng biên giới Kubernetes thành một mặt phẳng điều phối toàn cầu, tự động hóa việc phân bổ và cân bằng tải container trên mọi đám mây.", "Day 26 - Slide: Multi-Cluster Orchestration with Karmada"),
        ("Edge-to-Cloud Intelligent Inference Offloading", "Một hệ thống AI trên xe tự hành phân bổ tác vụ suy luận giữa 'Thiết bị Biên trên xe' (Edge Computer) và 'Máy chủ Đám mây' (Cloud AI) theo tiêu chí nào?",
         ["Gửi toàn bộ dữ liệu lên đám mây để xử lý", "Các tác vụ Nhận thức Khẩn cấp đòi hỏi thời gian thực (Phát hiện chướng ngại vật, Phanh khẩn cấp SLA < 10ms) BẮT BUỘC PHẢI CHẠY CỤC BỘ trên chip AI trên xe; Các tác vụ Lập kế hoạch lộ trình dài hạn, Dự báo thời tiết hoặc Cập nhật bản đồ HD được đẩy lên Đám mây xử lý", "Chỉ xử lý trên xe và cấm kết nối đám mây", "Tắt toàn bộ hệ thống AI khi xe đang chạy"], 1,
         "Phân bổ thông minh dựa trên độ trễ an toàn sống còn đảm bảo xe tự hành phản ứng tức thời trước các nguy hiểm trong khi vẫn tận dụng được sức mạnh đám mây cho các tính toán phức tạp.", "Day 26 - Slide: Intelligent Edge-to-Cloud Task Partitioning"),
        ("Cross-Cloud Secret Management with HashiCorp Vault", "Tại sao việc sử dụng HashiCorp Vault làm 'Hệ thống Quản lý Khóa Bí mật Tập trung' (Centralized Secret Store) lại vượt trội hơn việc dùng riêng lẻ AWS Secrets Manager và GCP Secret Manager?",
         ["Vì HashiCorp Vault miễn phí hoàn toàn", "Cung cấp một nguồn chân lý duy nhất (Single Source of Truth) độc lập với đám mây, Tự động cấp phát các Token xác thực động có thời hạn ngắn (Dynamic Ephemeral Credentials) cho ứng dụng trên cả AWS, GCP và On-Premise mà không cần cấu hình thủ công rải rác", "Vì HashiCorp Vault không cần mật khẩu", "Không có sự vượt trội nào"], 1,
         "HashiCorp Vault chuẩn hóa quy trình quản trị khóa bảo mật trên toàn bộ hạ tầng đa đám mây, loại bỏ rủi ro lộ lọt thông tin và phân mảnh chính sách an ninh.", "Day 26 - Slide: Centralized Multi-Cloud Secrets Management with Vault"),
        ("Observability Federation with OpenTelemetry Collector Exporters", "Làm thế nào để thu thập toàn bộ Metrics và Traces từ 3 đám mây khác nhau về một Bảng điều khiển Grafana duy nhất mà không bị thất lạc dữ liệu?",
         ["Mỗi đám mây mở một tab trình duyệt riêng", "Cài đặt OpenTelemetry Collector tại từng đám mây: Collector cục bộ thực hiện gom cụm, lọc PII và nén dữ liệu -> Xuất khẩu (Export) luồng Telemetry qua giao thức OTLP/gRPC an toàn về Cụm Lưu trữ Giám sát Trung tâm (Centralized M3DB / Grafana Tempo); Grafana truy vấn tập trung toàn bộ dữ liệu", "Gửi file log qua email mỗi tuần", "Tắt toàn bộ hệ thống giám sát"], 1,
         "Federated OpenTelemetry Collectors chuẩn hóa và hợp nhất toàn bộ dữ liệu quan sát từ mọi đám mây về một trung tâm chỉ huy duy nhất trong thời gian thực.", "Day 26 - Slide: Federated Multi-Cloud Observability Pipelines"),
        ("Hybrid Cloud Network Latency Jitter Mitigation with QUIC / HTTP/3", "Tại sao việc chuyển đổi giao thức truyền tải dữ liệu giữa On-Premise và Cloud từ TCP sang QUIC / HTTP/3 lại giúp giảm thiểu hiện tượng gián đoạn đường truyền?",
         ["Vì QUIC chỉ chạy trên điện thoại", "QUIC chạy trên nền UDP, tích hợp mã hóa TLS 1.3 mặc định, hỗ trợ Ghép kênh không nghẽn đầu hàng (No Head-of-Line Blocking) và Khả năng Phục hồi Kết nối Tức thời khi thay đổi địa chỉ IP (Connection Migration), duy trì luồng truyền dữ liệu mượt mà qua các mạng WAN không ổn định", "Vì TCP bị cấm trên đám mây", "Không có sự khác biệt nào"], 1,
         "QUIC/HTTP/3 triệt tiêu hoàn toàn sự chậm trễ do mất gói tin đơn lẻ trên đường truyền mạng diện rộng, tối ưu hóa thông lượng truyền dữ liệu cho các hệ thống lai.", "Day 26 - Slide: QUIC & HTTP/3 for Resilient Hybrid Cloud Data Transfers"),
        ("Cloud Bursting with Ephemeral Spot GPU Worker Nodes", "Khi kích hoạt Cloud Bursting trên AWS, làm thế nào để đảm bảo các máy chủ GPU tạm thời tự động tắt ngay lập tức khi hoàn thành tác vụ để không phát sinh chi phí thừa?",
         ["Đặt lịch hẹn trên điện thoại để kỹ sư vào tắt thủ công", "Sử dụng Kubernetes Autoscaler / Karpenter kết hợp Ray Autoscaler: Cấu hình tham số `scale-down-unneeded-time: 5m`; Ngay khi các Worker Pods hoàn thành tác vụ và rơi vào trạng thái nhàn rỗi quá 5 phút, Controller tự động tiêu hủy Pods và giải phóng máy chủ EC2 tức thời", "Khởi động lại toàn bộ cụm Kubernetes", "Không bao giờ tắt máy chủ"], 1,
         "Tự động thu hồi tài nguyên nhàn rỗi đảm bảo doanh nghiệp chỉ chi trả chính xác cho số giây tính toán thực tế trong các đợt tràn tải lên đám mây.", "Day 26 - Slide: Ephemeral Resource Teardown in Cloud Bursting"),
        ("Multi-Cloud IAM Federation with OIDC and SPIFFE/SPIRE", "Giao thức SPIFFE/SPIRE cung cấp danh tính bảo mật cho các AI Microservices giao tiếp xuyên đám mây như thế nào mà không cần dùng mật khẩu tĩnh?",
         ["Mỗi microservice tự tạo một mật khẩu riêng", "Cấp phát Danh tính Mật mã học Động dạng X.509 SVID (Cryptographic Workload Identity) tự động xoay vòng cho từng tiến trình; Các dịch vụ trên AWS và GCP tự động xác thực danh tính của nhau qua giao thức mTLS chuẩn mực mà không cần chia sẻ bất kỳ khóa bí mật tĩnh nào", "In mã nhận diện ra giấy", "Dùng địa chỉ IP để xác thực"], 1,
         "SPIFFE/SPIRE thiết lập nền tảng định danh Zero-Trust chuẩn mực quốc tế, cho phép các vi dịch vụ AI xác thực chéo xuyên biên giới đám mây an toàn tuyệt đối.", "Day 26 - Slide: Zero-Trust Multi-Cloud Workload Identity with SPIFFE/SPIRE"),
        ("Cross-Cloud Distributed Training Feasibility", "Tại sao việc cố gắng chạy một Job huấn luyện Tensor Parallelism (TP) phân tán rải rác trên cả AWS và GCP cùng lúc (Cross-Cloud Training) là điều BẤT KHẢ THI về mặt kỹ thuật?",
         ["Vì các công ty đám mây cấm kết nối với nhau", "Tensor Parallelism đòi hỏi băng thông cực hạn (900 GB/s) và độ trễ cực thấp (< 1 micro-giây) của bus NVLink; Độ trễ mạng WAN giữa các đám mây (hàng chục mili-giây) chậm hơn hàng nghìn lần, sẽ làm GPU bị đóng băng 99.9% thời gian chờ đợi", "Vì mô hình sẽ sinh ra kết quả sai", "Vì không thể cài đặt PyTorch trên 2 đám mây"], 1,
         "Giới hạn vật lý về độ trễ ánh sáng qua mạng diện rộng cấm kỵ tuyệt đối việc phân tán các cấu trúc song song đòi hỏi giao tiếp vi mô (như TP) xuyên qua ranh giới đám mây.", "Day 26 - Slide: Physical Latency Limits in Cross-Cloud Distributed Training"),
        ("Model Synchronization with P2P BitTorrent Protocols", "Khi cần phân phối một mô hình LLM kích thước 100GB tới 1,000 máy chủ Worker Nodes phân tán trên nhiều đám mây, tại sao giao thức P2P (như Kraken / Dragonfly) lại nhanh gấp 20 lần so with tải từ S3?",
         ["Vì BitTorrent là phần mềm nghe nhạc", "P2P cho phép các máy chủ Worker tự động chia sẻ và tải các mảnh dữ liệu của mô hình trực tiếp từ nhau qua mạng nội bộ song song (Peer-to-Peer Swarm), loại bỏ hoàn toàn nút thắt nghẽn băng thông tại máy chủ lưu trữ trung tâm", "Vì S3 cấm tải file lớn", "Vì BitTorrent tự động nén mô hình thành 1MB"], 1,
         "Phân phối ngang hàng P2P tận dụng tối đa băng thông mạng nội bộ của toàn bộ cụm máy chủ, phân phối các file mô hình khổng lồ tới hàng nghìn nút trong vài phút.", "Day 26 - Slide: P2P Model Distribution with Kraken & Dragonfly"),
        ("Data Sovereignty with Confidential Computing in Public Cloud", "Làm thế nào để một ngân hàng có thể chạy mô hình AI trên Đám mây Công cộng (AWS/GCP) mà vẫn tuân thủ 100% luật bảo vệ dữ liệu nội địa nghiêm ngặt?",
         ["Không bao giờ được sử dụng đám mây", "Sử dụng Điện toán Bảo mật Phần cứng (Confidential Computing on AMD SEV-SNP / Intel TDX / NVIDIA Hopper TEE): Dữ liệu và mô hình được mã hóa trực tiếp trong bộ nhớ RAM/VRAM bằng các khóa mã hóa do chính ngân hàng nắm giữ (Customer-Managed Keys), ngăn chặn hoàn toàn nhân viên của nhà cung cấp đám mây xem trộm dữ liệu", "Ký hợp đồng bảo mật bằng miệng", "Xóa tên ngân hàng khỏi hệ thống"], 1,
         "Confidential Computing thiết lập các vùng enclave phần cứng bất khả xâm phạm trên đám mây công cộng, bảo vệ tuyệt đối chủ quyền dữ liệu theo quy chuẩn quốc tế.", "Day 26 - Slide: Confidential Computing & Data Sovereignty Enclaves"),
        ("Multi-Cloud Load Balancing with Intelligent Geo-DNS", "Khi một trung tâm dữ liệu ở Châu Á bị đứt cáp quang biển, hệ thống Geo-DNS thông minh tự động chuyển hướng người dùng như thế nào?",
         ["Báo lỗi trang web không tồn tại", "Hệ thống Health Check liên tục đo lường độ trễ và tỉ lệ mất gói; Khi phát hiện kết nối Châu Á bị suy thoái, DNS tự động cập nhật bản ghi trong 5 giây, định tuyến người dùng sang Cụm Đám mây lân cận tại Châu Âu hoặc Bờ Tây Hoa Kỳ mà không làm gián đoạn dịch vụ", "Chờ 1 tháng để nối lại cáp quang", "Bắt người dùng tự đổi DNS bằng tay"], 1,
         "Geo-DNS thích ứng thông minh tự động điều hướng luồng giao thông mạng toàn cầu vòng qua các điểm nghẽn hạ tầng cáp quang, duy trì tính liên tục cho dịch vụ AI.", "Day 26 - Slide: Intelligent Geo-DNS Routing & Automated Failover"),
        ("Unified MLOps Pipeline across Hybrid Cloud (Vertex AI + SageMaker)", "Làm thế nào để một Pipeline Kubeflow duy nhất có thể điều phối bước Tiền xử lý Dữ liệu trên Google Cloud (BigQuery/TPU) và chuyển giao mô hình sang AWS SageMaker để phục vụ suy luận?",
         ["Mỗi bước phải viết một chương trình riêng và copy tay", "Sử dụng Kubeflow Pipelines với Cloud Providers SDKs & Centralized MLMD: Step 1 gọi Vertex AI API xử lý dữ liệu -> Lưu Artifacts vào S3/GCS chung -> Step 2 kích hoạt SageMaker Endpoint Deployment qua AWS Boto3 API; Toàn bộ trạng thái và Lineage được ghi vết tập trung trong cùng một DAG", "Không thể kết hợp Vertex AI và SageMaker", "Chỉ chạy được trên máy tính cá nhân"], 1,
         "Kubeflow trừu tượng hóa các API đám mây, cho phép kỹ sư xâu chuỗi các dịch vụ AI xuất sắc nhất của từng nhà cung cấp vào một quy trình làm việc liền mạch duy nhất.", "Day 26 - Slide: Cross-Cloud Workflow Orchestration with KFP")
    ]

    d26_hard = [
        ("Hyperscale Enterprise Multi-Cloud AI Master Architecture", "Thiết kế một Bản quy hoạch Kiến trúc AI Đa Đám mây Toàn diện (Master Hyperscale Multi-Cloud AI Architecture Blueprint) phục vụ 100 triệu người dùng toàn cầu trên 3 môi trường: Cụm Siêu máy tính On-Premise (10,000 GPUs), AWS và GCP. Trình bày chi tiết cấu trúc 5 phân tầng từ Mạng Lưới Cốt Lõi, Quản trị Dữ liệu Hợp nhất, Điều phối Công việc Toàn cầu, Bảo mật Zero-Trust đến Tự động Chuyển Mạch Thảm họa (Sub-Second Failover)?",
         ["Cài đặt 3 hệ thống riêng biệt và không cho liên kết với nhau", "Triển khai Kiến trúc Đa Đám mây 5 Phân tầng Chuẩn mực: 1. Global Core Network Fabric: Kênh truyền dẫn chuyên dụng Đa Đám mây (Dual AWS Direct Connect + GCP Dedicated Interconnect 400Gbps) với Mã hóa WireGuard mTLS và BGP Dynamic Peering; 2. Unified Storage & Data Layer: Ceph/WEKA All-Flash Storage (On-Premise) đồng bộ 2 chiều với S3/GCS qua Delta Lake CDC và Kraken P2P Model Distribution; 3. Global Orchestration Plane: Karmada Multi-Cluster Kubernetes kết hợp KubeRay điều phối linh hoạt giữa On-Premise Base Training và Cloud Bursting; 4. Zero-Trust Identity Mesh: SPIFFE/SPIRE Workload Attestation + HashiCorp Vault cấp phát khóa động cho toàn bộ microservices; 5. Global Traffic Management: Cloudflare Anycast + Envoy Multi-Cloud Gateway hỗ trợ Active-Active Routing và Sub-Second Disaster Failover", "Chạy toàn bộ trên một chiếc máy chủ đặt tại nhà", "Tắt toàn bộ hệ thống dự phòng để tiết kiệm chi phí"], 1,
         "Bản quy hoạch kiến trúc đa đám mây toàn diện 5 tầng thiết lập đỉnh cao của kỹ nghệ hạ tầng phân tán, dung hợp hoàn hảo sức mạnh của siêu máy tính nội bộ và tính linh hoạt vô hạn của điện toán đám mây toàn cầu.", "Day 26 - Slide: Master Enterprise Multi-Cloud AI Architecture Blueprint"),
        ("Mathematical Optimization of Multi-Cloud Traffic Routing under Joint SLA-Cost Constraints", "Chứng minh toán học và xây dựng Thuật toán Định tuyến Lưu lượng Đa Đám mây Tối ưu (Multi-Objective Traffic Allocation via Dual Decomposition) cực tiểu hóa Chi phí Hạ tầng và Phí Egress dưới ràng buộc Khắt khe về p99 Latency SLA $\\le 50\\text{ms}$?",
         ["Định tuyến ngẫu nhiên 33% cho mỗi đám mây", "Mô hình hóa bài toán dưới dạng Quy hoạch Lồi Khả vi (Convex Optimization with Dual Decomposition): Xét $K$ Trung tâm dữ liệu với hàm chi phí tính toán $C_k(x_k)$, chi phí Egress $E_k(x_k)$, và hàm độ trễ hàng đợi $D_k(x_k) = \\frac{1}{\\mu_k - x_k}$. Thiết lập bài toán tối ưu hóa tổng chi phí $\\min \\sum (C_k + E_k)$ dưới ràng buộc $\\sum x_k = \\lambda$ và $D_k(x_k) \\le D_{\\max}$. Sử dụng Thuật toán Phân rã Đối ngẫu (Dual Decomposition) tìm nghiệm cân bằng Karush-Kuhn-Tucker (KKT), tự động tính toán tỷ lệ phân bổ lưu lượng tối ưu $x_k^*$ cho từng đám mây theo thời gian thực", "Chọn đám mây có giá rẻ nhất cho tất cả các truy vấn", "Không có công thức toán học nào cho định tuyến mạng"], 1,
         "Thuật toán phân rã đối ngẫu KKT tự động điều tiết lưu lượng tối ưu toán học, đảm bảo doanh nghiệp luôn đạt được chi phí hạ tầng thấp nhất trong khi bảo vệ 100% cam kết SLA độ trễ cho khách hàng.", "Day 26 - Slide: Mathematical Formulation of Multi-Cloud Traffic Allocation"),
        ("Zero-Egress Multi-Cloud Model Serving with Decentralized Parameter Sharding", "Làm thế nào để phục vụ suy luận một mô hình 405B phân tán trên cả 3 đám mây (AWS, GCP, Azure) mà KHÔNG PHÁT SINH bất kỳ chi phí Egress nào khi người dùng truy cập?",
         ["Cắt mô hình thành 3 mảnh trên 3 đám mây và truyền tensor liên tục qua mạng internet tốn hàng triệu USD tiền Egress", "Triển khai Kiến trúc Nhân bản Không Phụ thuộc (Independent Region-Autonomous Serving Clusters): Nhân bản toàn bộ trọng số mô hình đã được nén INT4/FP8 vào VRAM của từng cụm máy chủ tại mỗi đám mây qua giao thức phân phối P2P 1 lần duy nhất; Mọi yêu cầu suy luận của người dùng tại vùng nào được xử lý trọn vẹn 100% tại chỗ (Local In-Region Execution), triệt tiêu hoàn toàn 100% chi phí xuất dữ liệu liên đám mây", "Cấm người dùng ở ngoài nước Mỹ truy cập", "Tắt toàn bộ các mô hình lớn"], 1,
         "Phục vụ tự trị tại từng khu vực kết hợp phân phối mô hình P2P triệt tiêu hoàn toàn lưu lượng truyền thông liên đám mây, mang lại độ trễ thấp nhất và chi phí vận hành tối ưu.", "Day 26 - Slide: Zero-Egress In-Region Autonomous Serving Architecture"),
        ("Cross-Cloud Automated Disaster Failover with State Rehydration in < 30 Seconds", "Khi toàn bộ trung tâm dữ liệu AWS `us-east-1` bị sập hoàn toàn do thảm họa thiên tai, quy trình Tự động Chuyển mạch Thảm họa và Tái thiết lập Trạng thái (Sub-30-Second Multi-Cloud State Rehydration to GCP) diễn ra theo những bước kỹ thuật chính xác nào?",
         ["Ngồi chờ AWS sửa xong sự cố", "Quy trình Chuyển mạch Tự trị 5 Giai đoạn: 1. Global Anycast Edge Probes phát hiện AWS mất liên lạc trong 3 giây và chuyển 100% DNS sang GCP Ingress; 2. GCP Kubernetes Cluster lập tức kích hoạt các Warm Standby Pods; 3. Nạp nóng trạng thái KV Cache và User Sessions từ Cụm Redis Global Replication (đồng bộ liên tục qua Kafka MirrorMaker); 4. Gắn kết các Volume lưu trữ bản sao từ Ceph Snapshot; 5. Toàn bộ 100% lưu lượng người dùng được phục vụ bình thường trên GCP trong 25 giây", "Khởi động lại toàn bộ máy tính công ty", "Đóng cửa dịch vụ vĩnh viễn"], 1,
         "Chuyển mạch tự động đa đám mây với cơ chế tái thiết lập trạng thái trong bộ nhớ bảo vệ doanh nghiệp an toàn tuyệt đối trước các thảm họa sập toàn bộ một nhà cung cấp đám mây.", "Day 26 - Slide: Sub-30-Second Multi-Cloud Automated Disaster Recovery"),
        ("Hybrid Cloud Bursting with Intelligent Data Pre-Staging Engines", "Khi kích hoạt Cloud Bursting đưa một Job huấn luyện đột biến lên AWS, làm thế nào để chuyển 50TB dữ liệu huấn luyện từ On-Premise lên đám mây mà không làm GPU trên AWS phải nhàn rỗi chờ đợi 10 tiếng?",
         ["Bật GPU trên AWS trước rồi mới bắt đầu copy dữ liệu", "Sử dụng Động cơ Nạp trước Dữ liệu Thông minh (Intelligent Data Pre-Staging & Streaming Ingestion Engine): 1. Hệ thống chỉ kích hoạt các CPU Storage Workers trên AWS để nạp trước 5% dữ liệu đầu tiên (Epoch 0 Buffer); 2. Cấp phát GPU Instances trên AWS và bắt đầu huấn luyện ngay lập tức trên 5% dữ liệu này; 3. Một tiến trình nền tiếp tục truyền tải ngầm 95% dữ liệu còn lại qua mạng chuyên dụng song song với quá trình tính toán của GPU, che giấu 100% thời gian truyền dữ liệu", "Hủy bỏ Job huấn luyện vì dữ liệu quá lớn", "Chỉ huấn luyện trên dữ liệu cũ"], 1,
         "Nạp dữ liệu gối đầu song song với tính toán cho phép bắt đầu huấn luyện trên đám mây ngay lập tức, loại bỏ hoàn toàn chi phí thuê GPU nhàn rỗi chờ nạp dữ liệu.", "Day 26 - Slide: Predictive Data Pre-Staging for Cloud Bursting"),
        ("Multi-Cloud Global Identity & Authorization Mesh with SPIRE and OIDC", "Thiết kế Kiến trúc Ủy quyền và Xác thực Toàn cầu Không Tin cậy (Universal Zero-Trust Identity Mesh with SPIRE Federation) quản lý 10,000 AI Microservices phân tán trên AWS, GCP, Azure và Bare-Metal?",
         ["Sử dụng chung một file cấu hình mật khẩu tĩnh cho tất cả các dịch vụ", "Triển khai Lưới Định danh Hợp nhất (SPIRE Server Federation across Clouds): Mỗi đám mây chạy một Cụm SPIRE Server độc lập xác thực các tiến trình cục bộ dựa trên phần cứng (Node Attestation); Các SPIRE Servers liên kết tin cậy với nhau (OIDC Federation & Bundle Exchange), tự động phát hành các chứng chỉ số mTLS X.509 ngắn hạn (SVIDs có TTL 1 giờ) cho phép mọi vi dịch vụ gọi API chéo đám mây an toàn tuyệt đối mà không cần quản lý API keys tĩnh", "Tắt toàn bộ hệ thống phân quyền", "Dùng địa chỉ email cá nhân để xác thực"], 1,
         "Lưới định danh SPIRE Federation thiết lập hạ tầng bảo mật Zero-Trust chuẩn mực quốc tế, loại bỏ hoàn toàn các lỗ hổng rò rỉ khóa bí mật trong các hệ thống đa đám mây phức tạp.", "Day 26 - Slide: Universal Zero-Trust Identity Mesh with SPIRE Federation"),
        ("Cross-Cloud Distributed Data Lineage & Provenance Graph with OpenLineage", "Làm thế nào để xây dựng một Đồ thị Nguồn gốc Dữ liệu Toàn cầu (Global Distributed Lineage Graph) theo dõi một tập dữ liệu bắt đầu từ BigQuery (GCP), biến đổi qua Spark (On-Premise) và huấn luyện mô hình trên SageMaker (AWS)?",
         ["Vẽ sơ đồ bằng tay trên bảng trắng", "Triển khai Kiến trúc OpenLineage Phân tán Hợp nhất (Unified OpenLineage Backend on Marquez/DataHub): Mỗi công cụ (BigQuery, Spark, SageMaker) được tích hợp OpenLineage Plugin tự động phát các sự kiện Lineage Events chuẩn hóa (Inputs, Outputs, Run Facets) qua API an toàn về Kho Siêu dữ liệu Trung tâm; Hệ thống tự động ghép nối các sự kiện thành một Đồ thị Có hướng Không Chu trình (Global DAG) duy nhất minh bạch 100%", "Bắt kỹ sư phải tự ghi nhật ký thủ công", "Không thể theo dõi nguồn gốc dữ liệu xuyên đám mây"], 1,
         "OpenLineage hợp nhất dòng chảy siêu dữ liệu xuyên biên giới đám mây, cung cấp khả năng kiểm toán nguồn gốc toàn diện cho mọi tài sản trí tuệ nhân tạo doanh nghiệp.", "Day 26 - Slide: Cross-Cloud Distributed Lineage with OpenLineage"),
        ("Hybrid Cloud Edge-AI Model Life-Cycle with Delta Updates & OTA", "Khi quản trị 500,000 thiết bị AI biên (Edge Cameras / IoT Devices) kết nối với Đám mây Lai, kiến trúc Nâng cấp Mô hình Qua Không gian (Over-The-Air Model Update Engine with Delta Weight Patching) tối ưu hóa việc phân phối như thế nào?",
         ["Gửi file mô hình đầy đủ 5GB tới từng thiết bị qua mạng 4G gây nghẽn mạng toàn quốc", "Triển khai Động cơ Cập nhật Trọng số Vi mô (Binary Delta Weight Patching & P2P Swarm Engine): Máy chủ trung tâm chỉ tính toán và xuất bản bản vá sai lệch nhị phân (Delta Patch dung lượng chỉ 20MB giữa Model v2 và Model v1) kết hợp nén Zstd; Các thiết bị biên tải bản vá nhỏ qua mạng di động, tự động tái tạo lại mô hình đầy đủ trên bộ nhớ cục bộ và chuyển đổi phiên bản không gián đoạn", "Bắt người dùng mang thiết bị đến trung tâm bảo hành để nâng cấp", "Không bao giờ nâng cấp mô hình trên thiết bị biên"], 1,
         "Bản vá trọng số vi sai (Delta Patching) giảm 99% dung lượng truyền tải mạng di động, cho phép nâng cấp trí thông minh cho hàng triệu thiết bị biên một cách tức thời và an toàn.", "Day 26 - Slide: Edge-AI Delta Weight Patching & OTA Deployment"),
        ("Multi-Cloud Kubernetes Network Mesh with Cilium ClusterMesh & eBPF", "Công nghệ Cilium ClusterMesh dựa trên eBPF thiết lập mạng giao tiếp giữa các Pods trên AWS EKS và GCP GKE với hiệu năng cực hạn như thế nào?",
         ["Sử dụng các cổng kết nối proxy chậm chạp", "Cilium ClusterMesh kết nối trực tiếp các mạng con của các cụm Kubernetes thông qua Công nghệ eBPF chạy trực tiếp trong Linux Kernel: Bỏ qua hoàn toàn iptables truyền thống, thực hiện định tuyến gói tin cấp độ socket (Socket-level BGP Routing) và mã hóa đường truyền phần cứng mTLS (IPsec/WireGuard in eBPF), đạt thông lượng tối đa của đường cáp quang và độ trễ gần bằng mạng nội bộ", "Chuyển dữ liệu thành file text và gửi qua HTTP", "Tắt toàn bộ hệ thống mạng của các Pods"], 1,
         "Cilium ClusterMesh với eBPF biến các cụm Kubernetes phân tán trên nhiều đám mây thành một mạng lưới phẳng duy nhất có hiệu năng chuyển tiếp gói tin tiệm cận mã máy nguyên bản.", "Day 26 - Slide: Multi-Cluster Networking with Cilium eBPF ClusterMesh"),
        ("Confidential Multi-Cloud Data Clean Rooms for Cross-Enterprise Collaboration", "Thiết kế một 'Phòng Làm Sạch Dữ liệu Đa Đám mây An toàn' (Confidential Data Clean Room on Multi-Cloud TEE) cho phép 2 tập đoàn đối thủ cạnh tranh cùng nạp dữ liệu để AI phân tích mà KHÔNG BÊN NÀO và KHÔNG CÔNG TY ĐÁM MÂY NÀO có thể xem trộm?",
         ["Lưu trữ dữ liệu trong một thư mục dùng chung có mật khẩu", "Triển khai Phòng Dữ liệu Sạch Dựa trên Enclave Phần cứng Đa Đám mây (Multi-Cloud Confidential Computing Enclave on AWS Nitro Enclaves / GCP Confidential Space): Dữ liệu của 2 bên được mã hóa bằng khóa riêng của từng bên trước khi tải lên; Chỉ duy nhất thuật toán AI đã được hai bên đồng thuận (Verified Algorithm Digest) mới được phép giải mã và tính toán bên trong vùng nhớ bảo mật phần cứng; Kết quả tổng hợp được xuất bản dưới dạng Differential Privacy", "Tin tưởng tuyệt đối vào nhân viên IT của công ty đám mây", "Không thể hợp tác dữ liệu an toàn giữa các đối thủ"], 1,
         "Confidential Data Clean Rooms mở khóa kỷ nguyên hợp tác dữ liệu chiến lược giữa các tập đoàn lớn mà không làm phương hại đến bí mật kinh doanh hay vi phạm các quy định chống độc quyền.", "Day 26 - Slide: Confidential Multi-Cloud Data Clean Rooms"),
        ("Dynamic Multi-Cloud Latency-Aware Request Routing with Reinforcement Learning", "Làm thế nào để xây dựng một Bộ định tuyến Lưu lượng AI Thích ứng (RL-Powered Multi-Cloud Request Router) tự động chuyển hướng các cuộc gọi API giữa AWS, GCP và On-Premise dựa trên biến động độ trễ và giá điện thời gian thực?",
         ["Cố định quy tắc định tuyến IF-ELSE", "Sử dụng Thuật toán Multi-Armed Bandit (Contextual Thompson Sampling with Real-Time Network Probing): Router liên tục đo lường độ trễ mạng RTT thực tế, độ dài hàng đợi GPU và chi phí biên của từng đám mây; Tự động tính toán xác suất định tuyến tối ưu để cực tiểu hóa chi phí tài chính trong khi duy trì 99.9% requests hoàn thành trong < 30ms", "Chọn ngẫu nhiên một đám mây bất kỳ", "Bắt người dùng tự chọn máy chủ"], 1,
         "Định tuyến thích ứng bằng học tăng cường tự động phản ứng với các biến động mạng và giá cả đám mây theo thời gian thực, duy trì SLA hoàn hảo với chi phí thấp nhất.", "Day 26 - Slide: RL-Powered Multi-Cloud Request Routing Engines"),
        ("Full-Stack Hybrid & Multi-Cloud Governance & Security Scorecard", "Thiết kế một Bảng Điều khiển Quản trị Kiến trúc Đa Đám mây Toàn diện (Full-Stack Multi-Cloud Architecture Scorecard) cho Hội đồng Quản trị Doanh nghiệp theo dõi 4 khía cạnh sống còn?",
         ["Chỉ hiển thị logo của các nhà cung cấp đám mây", "1. Dimension 1: Vendor Lock-in & Portability Index (Tỉ lệ mã nguồn và mô hình đạt chuẩn mở ONNX/K8s 100%); 2. Dimension 2: Cross-Cloud Egress Cost & Bandwidth Optimization (Tỉ lệ dữ liệu nén qua CDC); 3. Dimension 3: Zero-Trust Security & Identity Attestation (100% microservices định danh qua SPIRE); 4. Dimension 4: Disaster Recovery Readiness (RTO < 30s verified via Nightly Automated Chaos Drills)", "Chỉ hiển thị số lượng máy tính cá nhân", "In báo cáo ra giấy và cất vào kho lưu trữ"], 1,
         "Bảng điều khiển quản trị đa đám mây toàn diện cung cấp tầm nhìn chiến lược 360 độ, đảm bảo tính tự chủ công nghệ, an ninh mạng tối thượng và khả năng phục hồi thảm họa tức thời cho tập đoàn.", "Day 26 - Slide: Full-Stack Multi-Cloud Governance & Resilience Scorecard")
    ]
